INSERT INTO `craft_emailmessages` VALUES (1,'account_activation','en_gb','Activate your account','Hey {{user.friendlyName}},\n\nThanks for creating an account with {{siteName}}! To activate your account, click the following link:\n\n{{link}}\n\nIf you weren\'t expecting this email, just ignore it.','2019-05-28 12:12:16','2019-05-28 12:12:16','ba95a4f1-e7ad-4bab-91d5-d7689731e3ad'),(2,'verify_new_email','en_gb','Verify your new email address','Hey {{user.friendlyName}},\n\nPlease verify your new email address by clicking on this link:\n\n{{link}}\n\nIf you weren\'t expecting this email, just ignore it.','2019-05-28 12:12:16','2019-05-28 12:12:16','e4da09d7-17f0-497f-bb7c-4db4896ca36e'),(3,'forgot_password','en_gb','Reset your password','Hey {{user.friendlyName}},\n\nTo reset your {{siteName}} password, click on this link:\n\n{{link}}\n\nIf you weren\'t expecting this email, just ignore it.','2019-05-28 12:12:16','2019-05-28 12:12:16','a88085b0-92bc-4b38-ad3c-a85e1273ffb0'),(4,'test_email','en_gb','This is a test email from Craft','Hey {{user.friendlyName}},\n\nCongratulations! Craft was successfully able to send an email.\n\nHere are the settings you used:\n\n{% for key, setting in settings %}{{ key }}: {{ setting }}\n\n{% endfor %}','2019-05-28 12:12:16','2019-05-28 12:12:16','789ee09f-d889-437a-b004-618aec9bd001');
/*!40000 ALTER TABLE `craft_emailmessages` ENABLE KEYS */;
UNLOCK TABLES;

